const tasks = $input.all();
const chatId = $('Telegram Trigger').first().json.message.chat.id;

if (tasks.length === 0) {
  return [{ json: { message: "✅ You have no pending tasks! Enjoy your day.", chatId } }];
}

const business = tasks.filter(t => t.json.category === 'business');
const personal = tasks.filter(t => t.json.category === 'personal');

let msg = `📋 *Your Pending Tasks (${tasks.length} total)*\n\n`;

if (business.length > 0) {
  msg += `🏢 *Business (${business.length})*\n`;
  business.forEach(t => {
    const deadline = t.json.deadline ? ` — due ${t.json.deadline.split('T')[0]}` : '';
    const priority = t.json.priority === 'high' ? '🔴' : t.json.priority === 'medium' ? '🟡' : '🟢';
    msg += `${priority} ${t.json.title}${deadline}\n`;
  });
  msg += '\n';
}

if (personal.length > 0) {
  msg += `👤 *Personal (${personal.length})*\n`;
  personal.forEach(t => {
    const deadline = t.json.deadline ? ` — due ${t.json.deadline.split('T')[0]}` : '';
    const priority = t.json.priority === 'high' ? '🔴' : t.json.priority === 'medium' ? '🟡' : '🟢';
    msg += `${priority} ${t.json.title}${deadline}\n`;
  });
}

msg += `\n_🔴 high  🟡 medium  🟢 low_\nUse /done to complete a task.`;
return [{ json: { message: msg, chatId } }];

