const tasks = $input.all();
const chatId = $('Telegram Trigger').first().json.message.chat.id;

if (tasks.length === 0) {
  return [{ json: { message: "✅ No pending tasks to mark complete!", chatId, empty: true } }];
}

let msg = "✅ *Which task did you complete?*\nReply with the number:\n\n";
tasks.forEach((t, i) => {
  const emoji = t.json.category === 'business' ? '🏢' : '👤';
  const deadline = t.json.deadline ? ` — due ${t.json.deadline.split('T')[0]}` : '';
  msg += `*${i + 1}.* ${emoji} ${t.json.title}${deadline}\n`;
});

return [{
  json: {
    message: msg,
    chatId,
    tasks: tasks.map(t => t.json),
    empty: false
  }
}];

const reply = $('Telegram Trigger').first().json.message.text;
const taskIndex = parseInt(reply.trim()) - 1;
const tasks = $('Build Done List').first().json.tasks;

if (isNaN(taskIndex) || taskIndex < 0 || taskIndex >= tasks.length) {
  return [{ json: { error: true, message: "❌ Invalid number. Please send /done and try again.", taskId: null, title: null } }];
}

const task = tasks[taskIndex];
return [{ json: { error: false, taskId: task.id, title: task.title } }];

