const response = $input.first().json;
const text = response.content[0].text.trim();
const tasks = JSON.parse(text);
const telegramId = $('Telegram Trigger').first().json.message.chat.id;

return tasks.map(task => ({
  json: { ...task, user_telegram_id: telegramId, status: 'pending' }
}));

const taskIndex = $('Check Message Type').first().json.number - 1;
const tasks = $input.all();

if (taskIndex < 0 || taskIndex >= tasks.length) {
  return [{ json: { 
    error: true, 
    message: "❌ Invalid number. Send /done to see the list again.",
    chatId: $('Check Message Type').first().json.chatId
  }}];
}

const task = tasks[taskIndex];
return [{ json: { 
  error: false,
  taskId: task.json.id, 
  title: task.json.title,
  chatId: $('Check Message Type').first().json.chatId
}}];

const message = $('Telegram Trigger').first().json.message.text.trim();
const isNumber = /^\d+$/.test(message);

return [{
  json: {
    isNumber,
    number: isNumber ? parseInt(message) : null,
    text: message,
    chatId: $('Telegram Trigger').first().json.message.chat.id
  }
}];

const transcription = $input.first().json.text || $input.first().json.transcription || '';
const today = new Date().toISOString();

return [{
  json: {
    transcription: transcription,
    today: today
  }
}];
